uint64_t fn_17(uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {
  size_t i = 0;
  size_t cnt = 0;
  size_t total = 0;
  while (i < len && in[i] != 0) {
    if (i + 2 > len || i + in[i + 1] + 2 > len) {
      return -1;
    }
    total += in[i + 1];
    cnt++;
    i += in[i + 1] + 2;
  }
  if (cnt > out_cap) {
    return -1;
  }
  i = 0;
  for (size_t c = 0; c < cnt; c++) {
    out[c] = in[i];
    i += in[i + 1] + 2;
  }
  return (((uint64_t) cnt) << 32) | total;
}
